ALTER TABLE projects ADD COLUMN archived_at TEXT;
ALTER TABLE tasks ADD COLUMN parent_id TEXT REFERENCES tasks(id);
ALTER TABLE tasks ADD COLUMN effort_hours INTEGER NOT NULL DEFAULT 8 CHECK(effort_hours BETWEEN 0 AND 10000);
CREATE TABLE task_dependencies(org_id TEXT NOT NULL,project_id TEXT NOT NULL,task_id TEXT NOT NULL,predecessor_id TEXT NOT NULL,PRIMARY KEY(task_id,predecessor_id),FOREIGN KEY(org_id,project_id,task_id) REFERENCES tasks(org_id,project_id,id) ON DELETE CASCADE,FOREIGN KEY(org_id,project_id,predecessor_id) REFERENCES tasks(org_id,project_id,id) ON DELETE CASCADE,CHECK(task_id<>predecessor_id));
CREATE TABLE folders(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,project_id TEXT NOT NULL,name TEXT NOT NULL,parent_id TEXT REFERENCES folders(id),UNIQUE(org_id,project_id,id),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
ALTER TABLE documents ADD COLUMN folder_id TEXT REFERENCES folders(id);
ALTER TABLE documents ADD COLUMN archived_at TEXT;
ALTER TABLE documents ADD COLUMN audience TEXT NOT NULL DEFAULT 'project' CHECK(audience IN ('project','internal'));
CREATE TABLE comments(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,project_id TEXT NOT NULL,task_id TEXT,document_id TEXT,author_id TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,CHECK((task_id IS NULL)<>(document_id IS NULL)),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id),FOREIGN KEY(org_id,project_id,task_id) REFERENCES tasks(org_id,project_id,id) ON DELETE CASCADE,FOREIGN KEY(org_id,project_id,document_id) REFERENCES documents(org_id,project_id,id),FOREIGN KEY(org_id,author_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE task_documents(org_id TEXT NOT NULL,project_id TEXT NOT NULL,task_id TEXT NOT NULL,document_id TEXT NOT NULL,PRIMARY KEY(task_id,document_id),FOREIGN KEY(org_id,project_id,task_id) REFERENCES tasks(org_id,project_id,id) ON DELETE CASCADE,FOREIGN KEY(org_id,project_id,document_id) REFERENCES documents(org_id,project_id,id));
CREATE TABLE approvals(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,project_id TEXT NOT NULL,document_id TEXT NOT NULL,version_id TEXT NOT NULL REFERENCES document_versions(id),reviewer_id TEXT NOT NULL,requested_by TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),reason TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,decided_at TEXT,FOREIGN KEY(org_id,project_id,document_id) REFERENCES documents(org_id,project_id,id),FOREIGN KEY(org_id,reviewer_id) REFERENCES memberships(org_id,user_id),FOREIGN KEY(org_id,requested_by) REFERENCES memberships(org_id,user_id));
CREATE UNIQUE INDEX pending_approval ON approvals(version_id,reviewer_id) WHERE status='pending';
CREATE TABLE budget_revisions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,project_id TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents BETWEEN 0 AND 100000000000),reason TEXT NOT NULL,author_id TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id),FOREIGN KEY(org_id,author_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE budget_entries(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,project_id TEXT NOT NULL,label TEXT NOT NULL,category TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('actual','commitment','forecast')),amount_cents INTEGER NOT NULL CHECK(amount_cents BETWEEN 0 AND 100000000000),entry_date TEXT NOT NULL,author_id TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id),FOREIGN KEY(org_id,author_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE events(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,project_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',start_date TEXT NOT NULL,end_date TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('meeting','deadline','delivery','event')),created_by TEXT NOT NULL,created_at TEXT NOT NULL,CHECK(end_date>=start_date),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES memberships(org_id,user_id));
CREATE TABLE notifications(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,user_id TEXT NOT NULL,project_id TEXT NOT NULL,title TEXT NOT NULL,entity_id TEXT NOT NULL,dedupe_key TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL,UNIQUE(org_id,user_id,dedupe_key),FOREIGN KEY(org_id,user_id) REFERENCES memberships(org_id,user_id),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
CREATE TABLE templates(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL,structure TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(org_id,created_by) REFERENCES memberships(org_id,user_id));
CREATE INDEX notifications_recipient ON notifications(org_id,user_id,created_at);
CREATE INDEX comments_project ON comments(org_id,project_id);
CREATE INDEX events_project ON events(org_id,project_id,start_date);
